#!/bin/sh
set -eu
umask 077
# Passwords generated by Initialize-Environment.ps1 contain hexadecimal only.
case "$REDIS_PASSWORD" in ''|*[!0-9a-f]*) echo 'Invalid Redis password format' >&2; exit 1;; esac
printf 'bind 0.0.0.0\nprotected-mode yes\nrequirepass %s\nappendonly yes\nmaxmemory 256mb\nmaxmemory-policy noeviction\n' "$REDIS_PASSWORD" > /tmp/tutor-redis.conf
if [ "${REDIS_ENABLE_MODULES:-false}" = "true" ]; then
    printf 'loadmodule /usr/local/lib/redis/modules/rejson.so\nloadmodule /usr/local/lib/redis/modules/redisearch.so\n' >> /tmp/tutor-redis.conf
fi
exec redis-server /tmp/tutor-redis.conf
